namespace sv_9335a327cb9c41b0862378cea92b861f.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application steps">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <li class="step-item @stepClass">
                @if (stepIndex < CurrentStep)
                {
                    <button class="step-button completed" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">✓</span>
                        <span class="step-label">@Steps[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-button @stepClass">
                        <span class="step-icon">@(stepIndex + 1)</span>
                        <span class="step-label">@Steps[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] Steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepClass(int index)
    {
        if (index < CurrentStep) return "completed";
        if (index == CurrentStep) return "active";
        return "dimmed";
    }
}

@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company"
               @onchange="e => Update(Entry with { Company = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title"
               @onchange="e => Update(Entry with { Title = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                   disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool?)e.Value ?? false)" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

    private void Update(WorkEntry updated) => OnChanged.InvokeAsync(updated);

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        OnChanged.InvokeAsync(updated);
    }
}

@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<fieldset class="reference-form">
    <legend>Reference @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Entry.Name"
               @onchange="e => Update(Entry with { Name = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Entry.Relationship"
               @onchange="e => Update(Entry with { Relationship = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email"
                   @onchange="e => Update(Entry with { Email = (string?)e.Value ?? string.Empty })" />
        </div>

        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Entry.Phone"
                   @onchange="e => Update(Entry with { Phone = (string?)e.Value ?? string.Empty })" />
        </div>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public Reference Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void Update(Reference updated) => OnChanged.InvokeAsync(updated);
}

@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@FullName" @onchange="e => FullName = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @onchange="e => Email = (string?)e.Value ?? string.Empty" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @onchange="e => Phone = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Address" @onchange="e => Address = (string?)e.Value ?? string.Empty"></textarea>
    </div>

    <div class="step-actions">
        <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Data { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName = string.Empty;
    private string Email = string.Empty;
    private string Phone = string.Empty;
    private string Address = string.Empty;
    private string? ErrorMessage;
    private string? EmailError;
    private bool IsValidating;

    protected override void OnParametersSet()
    {
        if (Data is not null)
        {
            FullName = Data.FullName;
            Email = Data.Email;
            Phone = Data.Phone;
            Address = Data.Address;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                EmailError = "This email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       ShowRemove="@(Entries.Count > 1)"
                       OnChanged="entry => UpdateEntry(index, entry)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntry>? Data { get; set; }
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> Entries = new();
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Count > 0)
        {
            Entries = Data.Select(e => e).ToList();
        }
        else if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
        }
    }

    private void UpdateEntry(int index, WorkEntry entry)
    {
        Entries[index] = entry;
    }

    private void RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
    }

    private Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return Task.CompletedTask;
            }
        }

        return OnNext.InvokeAsync(Entries.ToList());
    }
}

@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@References[index]"
                       Index="index"
                       ShowRemove="@(References.Count > 2)"
                       OnChanged="entry => UpdateReference(index, entry)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? Data { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> References = new();
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Count > 0)
        {
            References = Data.Select(r => r).ToList();
        }
        else if (References.Count == 0)
        {
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private void UpdateReference(int index, Reference entry)
    {
        References[index] = entry;
    }

    private void RemoveReference(int index)
    {
        References.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference requires at least a name, relationship, and email.";
                return Task.CompletedTask;
            }
        }

        return OnNext.InvokeAsync(References.ToList());
    }
}

@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
