        <span class="char-count">@CoverLetter.Length / @MaxLength characters</span>
    </div>

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string? Data { get; set; }
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string CoverLetter = string.Empty;

    protected override void OnParametersSet()
    {
        if (Data is not null)
        {
            CoverLetter = Data;
        }
    }

    private Task HandleNext() => OnNext.InvokeAsync(CoverLetter);
}

@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (Submitted)
    {
        <div class="confirmation">
            <h3>✓ Application Submitted!</h3>
            <p>Your application has been received. Your application ID is <strong>#@ApplicationId</strong>.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-error">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal?.FullName</dd>
                <dt>Email</dt><dd>@Personal?.Email</dd>
                <dt>Phone</dt><dd>@Personal?.Phone</dd>
                <dt>Address</dt><dd>@Personal?.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @if (WorkEntries is not null)
            {
                @foreach (var entry in WorkEntries)
                {
                    <div class="review-item">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <span class="review-dates">
                            @entry.StartDate.ToString("MMM yyyy") –
                            @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                        </span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="review-item">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
