    {
        personalInfo = data;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntry> data)
    {
        workEntries = data;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> data)
    {
        references = data;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string data)
    {
        coverLetter = data;
        currentStep = 4;
    }

    private void GoBack() => currentStep = Math.Max(0, currentStep - 1);

    private void GoToStep(int step)
    {
