@rendermode InteractiveServer
@using sv_9335a327cb9c41b0862378cea92b861f.Models
@using sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Data="@personalInfo"
                              ApplicationService="@ApplicationService"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Data="@workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep Data="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep Data="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        ApplicationService="@ApplicationService"
                        OnBack="GoBack"
                        OnEditSection="GoToStep" />
            break;
    }
</div>

@code {
    private int currentStep;
    private PersonalInfo? personalInfo;
    private List<WorkEntry>? workEntries;
    private List<Reference>? references;
    private string? coverLetter;

    private void HandlePersonalNext(PersonalInfo data)
    {
        personalInfo = data;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntry> data)
    {
        workEntries = data;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> data)
    {
        references = data;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string data)
    {
        coverLetter = data;
        currentStep = 4;
    }

    private void GoBack() => currentStep = Math.Max(0, currentStep - 1);

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
        }
    }
}
