@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@FullName" @onchange="e => FullName = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @onchange="e => Email = (string?)e.Value ?? string.Empty" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @onchange="e => Phone = (string?)e.Value ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Address" @onchange="e => Address = (string?)e.Value ?? string.Empty"></textarea>
    </div>

    <div class="step-actions">
        <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Data { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName = string.Empty;
    private string Email = string.Empty;
    private string Phone = string.Empty;
    private string Address = string.Empty;
    private string? ErrorMessage;
    private string? EmailError;
    private bool IsValidating;

    protected override void OnParametersSet()
    {
        if (Data is not null)
        {
            FullName = Data.FullName;
            Email = Data.Email;
            Phone = Data.Phone;
            Address = Data.Address;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                EmailError = "This email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
        }
        finally
        {
            IsValidating = false;
        }
    }
}

