@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       ShowRemove="@(Entries.Count > 1)"
                       OnChanged="entry => UpdateEntry(index, entry)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntry>? Data { get; set; }
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> Entries = new();
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Count > 0)
        {
            Entries = Data.Select(e => e).ToList();
        }
        else if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
        }
    }

    private void UpdateEntry(int index, WorkEntry entry)
    {
        Entries[index] = entry;
    }

    private void RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
    }

    private Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return Task.CompletedTask;
            }
        }

        return OnNext.InvokeAsync(Entries.ToList());
    }
}

