@namespace sv_9335a327cb9c41b0862378cea92b861f.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@References[index]"
                       Index="index"
                       ShowRemove="@(References.Count > 2)"
                       OnChanged="entry => UpdateReference(index, entry)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? Data { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> References = new();
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Count > 0)
        {
            References = Data.Select(r => r).ToList();
        }
        else if (References.Count == 0)
        {
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private void UpdateReference(int index, Reference entry)
    {
        References[index] = entry;
    }

    private void RemoveReference(int index)
    {
        References.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference requires at least a name, relationship, and email.";
                return Task.CompletedTask;
            }
        }

        return OnNext.InvokeAsync(References.ToList());
    }
}

