+                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
+            </div>
+            @if (References is not null)
+            {
+                @foreach (var r in References)
+                {
+                    <div class="review-item">
+                        <strong>@r.Name</strong> (@r.Relationship)<br />
+                        @r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"• {r.Phone}" : "")
+                    </div>
+                }
+            }
+        </section>
+
+        <section class="review-section">
+            <div class="review-header">
+                <h3>Cover Letter</h3>
+                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
+            </div>
+            <p class="cover-letter-preview">@CoverLetter</p>
+        </section>
+
+        <div class="step-actions">
+            <button class="btn-outline" @onclick="OnBack">Back</button>
+            <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
+                @(IsSubmitting ? "Submitting..." : "Submit Application")
+            </button>
+        </div>
+    }
+</div>
+
+@code {
+    [Parameter] public PersonalInfo? Personal { get; set; }
+    [Parameter] public List<WorkEntry>? WorkEntries { get; set; }
+    [Parameter] public List<Reference>? References { get; set; }
+    [Parameter] public string? CoverLetter { get; set; }
+    [Parameter] public EventCallback OnBack { get; set; }
+    [Parameter] public EventCallback<int> OnEditSection { get; set; }
+    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;
+
+    private bool IsSubmitting;
+    private bool Submitted;
+    private int ApplicationId;
+    private string? ErrorMessage;
+
+    private async Task HandleSubmit()
+    {
+        if (Personal is null || WorkEntries is null || References is null)
+        {
+            ErrorMessage = "Application data is incomplete.";
+            return;
+        }
+
+        IsSubmitting = true;
+        ErrorMessage = null;
+
+        try
+        {
+            var application = new JobApplication(
+                Personal,
+                new WorkHistory(WorkEntries),
+                References,
+                CoverLetter ?? string.Empty
+            );
+
+            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
+            Submitted = true;
+        }
+        catch (Exception ex)
+        {
+            ErrorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            IsSubmitting = false;
+        }
+    }
+}
+

