    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;
    private string StartDateValue => Entry.StartDate.ToString("yyyy-MM-dd");
    private string EndDateValue => Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

    private void HandleCompanyChange(ChangeEventArgs e)
    {
        var updated = Entry with { Company = (string?)e.Value ?? string.Empty };
        OnChanged.InvokeAsync(updated);
    }

    private void HandleTitleChange(ChangeEventArgs e)
    {
        var updated = Entry with { Title = (string?)e.Value ?? string.Empty };
        OnChanged.InvokeAsync(updated);
    }

    private void HandleStartDateChange(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var date = string.IsNullOrEmpty(val) ? DateTime.Today : DateTime.Parse(val);
        var updated = Entry with { StartDate = date };
        OnChanged.InvokeAsync(updated);
    }

    private void HandleEndDateChange(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        var updated = Entry with { EndDate = endDate };
        OnChanged.InvokeAsync(updated);
    }

    private void HandleCurrentChange(ChangeEventArgs e)
    {
        var isCurrent = (bool?)e.Value ?? false;
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        OnChanged.InvokeAsync(updated);
    }

    private void HandleDescriptionChange(ChangeEventArgs e)
    {
        var updated = Entry with { Description = (string?)e.Value ?? string.Empty };
        OnChanged.InvokeAsync(updated);
    }
}

