    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;
    private string EndDateValue => Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

    private void Update(WorkEntry updated) => OnChanged.InvokeAsync(updated);

    private void HandleEndDateChange(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        Update(Entry with { EndDate = endDate });
    }

    private void HandleCurrentChange(ChangeEventArgs e)
    {
        var isCurrent = (bool?)e.Value ?? false;
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        OnChanged.InvokeAsync(updated);
    }
}

